def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find the straight line that is not the background.
    line_col = next((c for c in range(w)
                     if len({grid[r][c] for r in range(h)}) == 1
                     and grid[0][c] != bg), None)
    line_row = next((r for r in range(h)
                     if len(set(grid[r])) == 1 and grid[r][0] != bg), None)

    out = [row[:] for row in grid]
    if line_col is not None:
        side = -1 if any(grid[r][line_col-1] != bg for r in range(h)) and line_col > 0 else 1
        obj_cols = [c for c in range(w) if c != line_col and
                    any(grid[r][c] != bg and grid[r][c] != grid[0][line_col] for r in range(h))]
        if obj_cols:
            c = min(obj_cols) - 1 if side == -1 else max(obj_cols) + 1
            if 0 <= c < w:
                for r in range(h):
                    out[r][c] = 8
    elif line_row is not None:
        side = -1 if line_row > 0 and any(v != bg for v in grid[line_row-1]) else 1
        obj_rows = [r for r in range(h) if r != line_row and
                    any(v != bg and v != grid[line_row][0] for v in grid[r])]
        if obj_rows:
            r = min(obj_rows) - 1 if side == -1 else max(obj_rows) + 1
            if 0 <= r < h:
                for c in range(w):
                    out[r][c] = 8
    return out
